public class BehaviouralPatterns2 {
    abstract static class DataProcessor {
        final void process() { loadData(); transform(); save(); }
        abstract void loadData();
        abstract void transform();
        void save() { System.out.println("Saved"); } // default hook
    }
    static class JSONProcessor extends DataProcessor {
        void loadData()   { System.out.println("Loading JSON"); }
        void transform()  { System.out.println("Transforming JSON"); }
    }
    public static void main(String[] args) {
        new JSONProcessor().process();
    }
}
